mapper.select:
SELECT count(*)
FROM member
WHERE  username=#{username}

mapper.insert:
 INSERT INTO member (
 	member_id, username, password, name, sex, birthdate, 
 	phone, post, addr1, addr2, profile_desc
 ) 
 VALUES (
	 	MEM_MID_SEQ.NEXTVAL, #{username}, #{password}, #{name}, #{sex}, 
 	TO_DATE(#{birthdate}, 'YYYYMMDD'), #{phone}, #{post}, #{addr1}, #{addr2}, #{profile_desc}
 )
